(()=>{const overlay=document.getElementById('bpStoreOverlay'),frame=document.getElementById('bpStoreFrame');let loaded=false;window.bpOpenTicketStore=()=>{overlay.hidden=false;if(!loaded){frame.srcdoc=new TextDecoder().decode(Uint8Array.from(atob(''),c=>c.charCodeAt(0)));loaded=true}else frame.contentWindow?.postMessage('bp-store-refresh','*')};window.bpCloseTicketStore=()=>{overlay.hidden=true};window.bpRefreshTicketStore=()=>{if(loaded)frame.contentWindow?.postMessage('bp-store-refresh','*')};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!overlay.hidden)window.bpCloseTicketStore()})})();